INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('python-beginner', 'Python Beginner', 'Programming', 'Master the fundamentals of Python programming from scratch with hands-on exercises, logical problem-solving, and foundational scripts.', 'A structured, beginner-friendly immersion into modern Python programming. Designed for complete beginners, school and college students, and professionals with zero prior coding experience. You will understand programming fundamentals, data types, control flow, functions, modular architecture, file handling, and basic object-oriented principles while building functional command-line applications and practical automation scripts.', '/images/courses/python-beginner.jpg', '40 Days', 'Beginner', 'Classroom / In-Person', TRUE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday (6 Days/Week)","classTime":"Morning (7:00 AM – 8:30 AM) & Evening (5:00 PM – 6:30 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & scholarship options (NPR)', ARRAY['Python 3.12', 'VS Code', 'Git & GitHub', 'Python Data Types & Variables', 'Control Flow & Loops', 'Functions & Scope', 'File Handling & JSON', 'OOP Fundamentals', 'Virtual Environments', 'CLI Scripting'], ARRAY['Complete beginners with no prior programming background wanting a clean start in coding.', 'School (+2) and university students in BCA, BSc.CSIT, BIT, or engineering seeking strong programming basics.', 'Professionals and non-technical staff aiming to automate repetitive daily computer tasks.', 'Enthusiasts preparing for advanced pathways in Web Development, Data Science, or Artificial Intelligence.'], ARRAY['Basic computer literacy (operating a browser, file management, and typing).', 'A personal laptop for hands-on classroom lab sessions and code exercises.', 'Passion and dedication to learn logical problem solving.'], ARRAY['Write clean, idiomatic, and readable Python code following PEP 8 conventions.', 'Solve algorithmic problems using core data structures: lists, dictionaries, tuples, and sets.', 'Perform file reading, writing, and parsing of text, CSV, and structured JSON data.', 'Build modular, reusable functions and apply foundational Object-Oriented Programming (OOP).', 'Use Git for version control and manage code repositories on GitHub.'], '[{"title":"Automated Personal Finance & Expense Tracker","technologies":["Python","CSV / JSON","CLI","Git"],"description":"Command-line tool that parses income and expenditure logs, computes monthly category analytics, and outputs formatted financial summaries.","type":"CLI Application"},{"title":"Interactive Text RPG & Quest Engine","technologies":["Python","OOP","Data Structures"],"description":"Turn-based role-playing game utilizing object-oriented classes for characters, inventory management, battle mechanics, and game-save persistence.","type":"Interactive Game"},{"title":"Automated File Organizer & System Cleanup Utility","technologies":["Python","OS Module","Shutil","Logging"],"description":"Desktop background script that automatically categorizes downloaded files into sorted folders by extension and generates audit logs.","type":"Automation Script"}]'::jsonb, '[]'::jsonb, ARRAY['Junior Python Programmer', 'Automation Script Developer', 'Technical Support Specialist', 'Foundation for Data Science & AI', 'Foundation for Backend Development'], '{"name":"Senior Python Specialist","role":"Lead Python Instructor","experience":"6+ years in Python engineering and technical training","specialization":"Python Core, Automation, Logic Building, Algorithm Design","isPlaceholder":true}'::jsonb, '[{"question":"Do I need any previous coding experience before enrolling?","answer":"No! This course is engineered from absolute ground zero. We teach computer logic, syntax, and problem-solving step by step."},{"question":"What is the duration and daily commitment for this 40-day course?","answer":"The course runs for 40 instructional days (approx. 6–7 weeks), Sunday through Friday, with 1.5 to 2 hours of live lectures and lab work daily."},{"question":"Will I receive a certificate upon completion?","answer":"Yes. Students who complete the practical coursework, lab assignments, and the capstone project receive the verified Navya Ed Tech Course Completion Certificate."}]'::jsonb, 'Python Beginner Course in Nepal (40 Days) | Learn Python Kathmandu', 'Start your coding journey with our 40-day Python Beginner course in Kathmandu at Navya Ed Tech. Hands-on coding, practical projects, and personalized mentorship.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('python-advance', 'Python Advance', 'Programming', 'Elevate your Python skills to production-grade engineering with asynchronous concurrency, design patterns, metaclasses, and backend API microservices.', 'An intensive, advanced software engineering track tailored for developers with Python foundations who want to build high-performance, robust, and scalable systems. Dive deep into internal Python object models, dunder protocols, asynchronous I/O with AsyncIO, concurrency with multiprocessing, decorators, context managers, clean architecture patterns, and production deployment.', '/images/courses/python-advance.jpg', '40 Days', 'Advanced', 'Classroom / In-Person', FALSE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday (6 Days/Week)","classTime":"Morning (7:00 AM – 8:30 AM) & Evening (5:30 PM – 7:00 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['Python 3.12+', 'AsyncIO & AIOHTTP', 'Multiprocessing & Threading', 'Decorators & Generators', 'Metaclasses & Dunder Methods', 'FastAPI & Pydantic', 'SQLAlchemy ORM', 'Docker & Containerization', 'PyTest & Mocking', 'Redis Caching'], ARRAY['Developers with basic or intermediate Python knowledge looking to level up to senior engineering standards.', 'Backend programmers wanting to master asynchronous APIs, thread-safe architectures, and microservices.', 'Data engineers and AI developers needing high-performance computing, memory optimization, and parallel processing.', 'IT graduates seeking commercial software engineering roles in Nepal and international remote tech companies.'], ARRAY['Familiarity with Python syntax, loops, functions, basic OOP, and common data structures.', 'Understanding of basic terminal commands and Git version control.', 'A personal laptop suitable for running Docker containers and development environments.'], ARRAY['Write scalable, non-blocking asynchronous Python applications using AsyncIO and coroutines.', 'Implement enterprise software design patterns: Factory, Singleton, Observer, and Dependency Injection.', 'Master advanced Python internals: memory management, garbage collection, descriptors, and metaclasses.', 'Architect and deploy high-performance REST APIs with FastAPI, Pydantic, and SQLAlchemy.', 'Write comprehensive unit and integration test suites using PyTest, fixtures, and mocks.'], '[{"title":"High-Throughput Asynchronous Web Scraping & Ingestion Engine","technologies":["Python","AsyncIO","AIOHTTP","BeautifulSoup","PostgreSQL"],"description":"Distributed web data scraper capable of querying hundreds of concurrent endpoints, handling rate limits, retry backoffs, and structured database storage.","type":"Asynchronous Service"},{"title":"Distributed Task Queue & Background Worker System","technologies":["Python","Redis","Multiprocessing","Docker"],"description":"Lightweight distributed task scheduler with worker worker pools, priority message queuing, failed job retries, and task execution metrics.","type":"System Tool"},{"title":"Production-Grade Microservice with FastAPI & JWT Authentication","technologies":["FastAPI","Pydantic","SQLAlchemy","JWT","Docker"],"description":"Fully containerized microservice featuring role-based access control, database connection pooling, auto-generated OpenAPI documentation, and test suites.","type":"Backend Microservice"}]'::jsonb, '[]'::jsonb, ARRAY['Senior Python Developer', 'Backend Software Engineer', 'API & Microservices Engineer', 'Data Infrastructure Engineer', 'Python Automation Architect'], '{"name":"Principal Systems Architect","role":"Advanced Python Track Lead","experience":"8+ years building high-concurrency microservices and Python architectures","specialization":"AsyncIO, Distributed Systems, FastAPI, Clean Architecture","isPlaceholder":true}'::jsonb, '[{"question":"Who should take Python Advance over Python Beginner?","answer":"If you already understand Python loops, functions, lists, dictionaries, and classes, this course is designed for you. It skips the basics and jumps straight into concurrency, architecture, and production APIs."},{"question":"Are FastAPI and Docker covered in this course?","answer":"Yes! You will build and containerize modern RESTful APIs using FastAPI, Pydantic, SQLAlchemy, and Docker."}]'::jsonb, 'Python Advance Course in Nepal (40 Days) | Advanced Python Kathmandu', 'Master advanced Python in Kathmandu. Learn AsyncIO, design patterns, FastAPI, and scalable system engineering in our intensive 40-day course at Navya Ed Tech.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('web-development', 'Web Development', 'Web Development', 'Build modern responsive websites and interactive web applications using HTML5, CSS3, modern JavaScript ES6+, React, and backend API integration.', 'A practical, industry-aligned web development program covering the complete journey of modern web craftsmanship. Starting with semantic HTML5 and responsive modern CSS layouts (Flexbox & Grid), transitioning into modern JavaScript ES6+ application logic, and culminating in component-driven React frontend architecture, state management, and connecting to RESTful APIs.', '/images/courses/web-development.jpg', '45 Days', 'Beginner to Intermediate', 'Classroom / In-Person', TRUE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday (6 Days/Week)","classTime":"Morning (7:00 AM – 9:00 AM) & Evening (5:00 PM – 7:00 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['HTML5 & Semantic Markup', 'Modern CSS3 (Flexbox, Grid)', 'Tailwind CSS', 'JavaScript ES6+', 'DOM Manipulation & Events', 'React 18+', 'React Hooks & Component State', 'REST APIs & Fetch / Axios', 'Node.js & Express Basics', 'Git & GitHub', 'Vercel & Netlify Deployment'], ARRAY['Aspiring web developers and software engineers wanting an end-to-end practical foundation.', 'Students in IT, BCA, BSc.CSIT, or Engineering seeking hands-on project experience.', 'Career switchers wanting to build real, deployable commercial websites and web apps.', 'Graphic and UI designers who want to bring their web designs to life with clean code.'], ARRAY['Basic computer literacy and a passion for technology and design.', 'No prior programming or web development experience required.', 'A personal laptop for development labs and coding assignments.'], ARRAY['Build fully responsive, accessible websites that render seamlessly across mobile, tablet, and desktop.', 'Write modular, clean JavaScript ES6+ code with array methods, promises, and async/await.', 'Develop modern single-page applications (SPAs) with React 18+ and component hierarchies.', 'Integrate third-party RESTful APIs and handle asynchronous data fetching, caching, and state.', 'Deploy production web applications to cloud hosts like Vercel and showcase on GitHub.'], '[{"title":"Modern E-Commerce Storefront with Product Filtering & Cart","technologies":["React","Tailwind CSS","JavaScript ES6+","Local Storage"],"description":"Complete online retail interface with product catalog, search filters, category tags, responsive shopping cart, and mock checkout flow.","type":"React Web Application"},{"title":"Interactive Real-Time Task & Kanban Board","technologies":["React","CSS Grid","REST APIs","Vercel"],"description":"Project management application featuring drag-and-drop status columns, task creation, tagging, priority indicators, and persistent state.","type":"Interactive Dashboard"},{"title":"Dynamic Weather & City Information Portal with Live APIs","technologies":["HTML5","CSS3","JavaScript","Fetch API"],"description":"Real-time meteorological web app utilizing geolocation, external REST weather APIs, dynamic theme switching, and 5-day forecast visualizations.","type":"API-Driven Web App"}]'::jsonb, '[]'::jsonb, ARRAY['Junior Frontend Developer', 'Web Developer', 'React Developer', 'UI/Web Engineer', 'Freelance Web Specialist'], '{"name":"Senior Frontend Architect","role":"Web Development Faculty Lead","experience":"7+ years engineering web applications in React and JavaScript","specialization":"Modern Frontend Architecture, React, Tailwind CSS, Responsive Design","isPlaceholder":true}'::jsonb, '[{"question":"Do I need design skills before joining Web Development?","answer":"Not at all! We teach the principles of clean UI layout, typography, colors, and responsive design alongside HTML, CSS, and React."},{"question":"What is the schedule and total duration for 45 days?","answer":"The course spans 45 instructional days (approx. 7.5 weeks), Sunday to Friday, with 2 hours of daily interactive instruction and mentored lab coding."},{"question":"Will I learn how to host and deploy my web projects?","answer":"Yes! You will learn Git version control, push your work to GitHub, and deploy live websites to cloud platforms like Vercel and Netlify."}]'::jsonb, 'Web Development Course in Nepal (45 Days) | Learn Web Design Kathmandu', 'Master web development in Nepal with Navya Ed Tech. Learn HTML5, CSS3, JavaScript, React, and Git in our 45-day hands-on course in Kathmandu.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('scratch-beginner', 'Scratch Beginner', 'Kids Coding', 'An exciting, playful introduction to computational thinking, animation, and storytelling using visual block-based programming for young learners.', 'A fun and engaging program designed specifically for school students and young beginners to cultivate problem-solving, creativity, and computational thinking. Students learn core computer science concepts—such as sequences, loops, conditionals, events, and variables—through interactive animations, musical instruments, and simple arcade games created in Scratch 3.0.', '/images/courses/scratch-beginner.jpg', '30 Days', 'Beginner', 'Classroom / In-Person', FALSE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday (6 Days/Week)","classTime":"Morning (8:00 AM – 9:30 AM) & Afternoon (4:00 PM – 5:30 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & junior batch schedules (NPR)', ARRAY['Scratch 3.0', 'Visual Block-Based Coding', 'Sprite Creation & Costumes', 'Sound Effects & Audio FX', 'Sequencing & Event Handling', 'Loops & Iteration', 'Conditional Logic (If-Else)', 'Basic Variables & Scores', 'Interactive Storytelling'], ARRAY['School students (Ages 7–14) curious about how computers, games, and animations work.', 'Young beginners with zero computer programming experience looking for a joyful start.', 'Parents seeking structured STEM and computational thinking education for their children.', 'Educators and creative minds wanting to explore educational coding tools.'], ARRAY['Basic ability to read, click a computer mouse, and follow simple instructions.', 'No prior programming or typing knowledge required.', 'Curiosity, enthusiasm, and imagination!'], ARRAY['Understand the foundational logic of programming: instructions, events, and loops.', 'Design and animate interactive sprites with custom costumes, backdrops, and sounds.', 'Build engaging mini-games with player movement, collision detection, and score tracking.', 'Cultivate algorithmic problem-solving and structured logical thinking from an early age.', 'Publish and present completed Scratch projects proudly to peers and parents.'], '[{"title":"Interactive Animated Storybook with Sound FX","technologies":["Scratch 3.0","Broadcast Events","Costumes","Sound"],"description":"Multi-scene interactive fairy tale or cartoon story where user clicks trigger character dialogues, sound effects, and backdrop transitions.","type":"Interactive Story"},{"title":"Fruit Catcher Arcade Game","technologies":["Scratch 3.0","Loops","Conditionals","Variables"],"description":"Fast-paced arcade game where players move a bowl to catch falling fruit, gain points for apples, and lose lives for obstacles.","type":"Arcade Game"},{"title":"Virtual Musical Instrument & Dance Party Simulator","technologies":["Scratch 3.0","Audio Blocks","Key Press Events"],"description":"Interactive keyboard synthesizer where number keys trigger drum beats, piano notes, and dancing character animations.","type":"Music App"}]'::jsonb, '[]'::jsonb, ARRAY['Foundation for Scratch Advanced', 'Foundation for Python Programming', 'STEM & Robotics Readiness', 'Creative Digital Arts & Game Design'], '{"name":"Junior STEM & Coding Educator","role":"Creative Coding Lead","experience":"5+ years specializing in K-12 STEM pedagogy and Scratch education","specialization":"Scratch 3.0, Computational Thinking, Game-Based Learning","isPlaceholder":true}'::jsonb, '[{"question":"What age group is Scratch Beginner suitable for?","answer":"Scratch Beginner is ideally designed for children aged 7 to 14. No prior computer coding experience is needed."},{"question":"Do parents need to attend the classes with their child?","answer":"No. Our instructors and lab assistants provide hands-on, step-by-step guidance in every session. Parents are welcome during project presentations!"},{"question":"Can projects created in class be played at home?","answer":"Yes! Scratch projects run inside any web browser and can be shared with family and friends anywhere via Scratch project links."}]'::jsonb, 'Scratch Beginner Coding Course for Kids (30 Days) | Nepal Kathmandu', 'Introduce your child to coding with our 30-day Scratch Beginner course in Kathmandu at Navya Ed Tech. Fun, visual, creative game development for kids.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('scratch-advanced', 'Scratch Advanced', 'Kids Coding', 'Take block coding to the next level with multi-level 2D games, physics simulations, custom blocks, cloning, and game state mechanics.', 'A project-heavy advanced Scratch track for students who have mastered basic block coding and want to engineer sophisticated 2D games and simulations. Students explore gravity and jump physics, collision detection algorithms, cloning for particle effects, custom procedural blocks ("My Blocks"), broadcast messaging hierarchies, and cloud variable high-score leaderboards.', '/images/courses/scratch-advanced.jpg', '30 Days', 'Intermediate to Advanced', 'Classroom / In-Person', FALSE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday (6 Days/Week)","classTime":"Morning (8:00 AM – 9:30 AM) & Afternoon (4:00 PM – 5:30 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & junior batch schedules (NPR)', ARRAY['Scratch 3.0 Advanced', 'Custom Procedures (My Blocks)', 'Sprite Cloning & Particle Systems', 'Gravity & Velocity Physics', 'Hitbox Collision Algorithms', 'Broadcast Message Hierarchies', 'List Data Structures & Inventories', 'Cloud Variables & Leaderboards', 'Game State Machines (Menu/Play/Over)'], ARRAY['Graduates of Scratch Beginner who want to build more complex, commercial-style arcade games.', 'School students with basic Scratch familiarity ready to learn advanced game mechanics and physics.', 'Young creators fascinated by game design, mechanics, animation polish, and level design.', 'Students preparing to transition smoothly to text-based programming in Python.'], ARRAY['Completion of Scratch Beginner or practical familiarity with loops, conditionals, and variables in Scratch.', 'Comfortable using a mouse and keyboard.', 'A personal laptop for class coding labs.'], ARRAY['Implement realistic 2D game physics including acceleration, gravity, jumping, and momentum.', 'Use sprite cloning efficiently to create enemy waves, projectile bullets, and particle explosions.', 'Organize complex codebases using modular custom procedures ("My Blocks") with inputs.', 'Manage complete game lifecycles: start menu, pause state, health meters, multi-levels, and game-over screens.', 'Store high scores and inventory items using lists and Scratch cloud variables.'], '[{"title":"Multi-Level 2D Platformer with Gravity & Jump Physics","technologies":["Scratch 3.0","Custom Blocks","Physics Velocity","Hitboxes"],"description":"Complete scrolling platformer game featuring running, jumping on platforms, collecting coins, dodging hazards, and transitioning through distinct levels.","type":"Platformer Game"},{"title":"Space Defenders Arcade Shooter with Enemy Waves & Boss Battles","technologies":["Scratch 3.0","Cloning","Lists","Health Meters"],"description":"Top-down arcade shooter utilizing dynamic sprite cloning for laser bullets and enemy ships, featuring progressive difficulty and boss battle phases.","type":"Arcade Shooter"},{"title":"Interactive Virtual Pet Simulator with State Management","technologies":["Scratch 3.0","Lists","Timers","State Machine"],"description":"Digital pet game where hunger, happiness, and energy levels decrease over time, requiring players to feed, train, and interact with the pet.","type":"Simulation Game"}]'::jsonb, '[]'::jsonb, ARRAY['Game Design & Mechanics Pathway', 'Direct Progression to Python Programming', 'Advanced Robotics & STEM Competitions', 'Algorithmic Problem Solving'], '{"name":"Game Development & STEM Mentor","role":"Advanced Junior Track Lead","experience":"6+ years in game mechanics, creative technology, and youth STEM coaching","specialization":"Game Physics, Scratch Advanced, Algorithmic Thinking for Youth","isPlaceholder":true}'::jsonb, '[{"question":"How is Scratch Advanced different from Scratch Beginner?","answer":"Scratch Advanced introduces complex math, gravity physics, cloning algorithms, list arrays, custom procedural blocks, and multi-level game mechanics that go far beyond introductory animations."},{"question":"Does this course prepare students for Python?","answer":"Yes! The logical patterns taught here—custom functions, parameters, data arrays, and game state loops—map directly to Python syntax, making the transition seamless."}]'::jsonb, 'Scratch Advanced Game Coding for Kids (30 Days) | Nepal Kathmandu', 'Master 2D game physics, custom blocks, and advanced Scratch coding in Nepal. Intensive 30-day course for young game creators at Navya Ed Tech.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO courses (slug, title, category, "shortDescription", description, "heroImage", duration, level, mode, featured, "upcomingBatch", fee, technologies, "targetAudience", prerequisites, outcomes, projects, curriculum, "careerPaths", instructor, faqs, "seoTitle", "seoDescription") VALUES ('data-science', 'Data Science', 'Data & AI', 'Extract actionable insights from raw data using Python, Pandas, statistical modeling, exploratory data analysis, and machine learning pipelines.', 'A rigorous, industry-relevant curriculum designed to transform learners into competent data practitioners. Master data wrangling, cleaning, exploratory data analysis (EDA), statistical inference, data visualization with Seaborn and Matplotlib, SQL database querying, and predictive modeling using Scikit-Learn machine learning algorithms.', '/images/courses/data-science.jpg', '50 Days', 'Intermediate to Advanced', 'Classroom / In-Person', TRUE, '{"startDate":"Next batch starting soon [Inquire for exact schedule]","classDays":"Sunday – Friday (6 Days/Week)","classTime":"Morning (7:00 AM – 9:00 AM) & Evening (5:30 PM – 7:30 PM)","seatsStatus":"Admissions Open","location":"Kathmandu Campus / Online Live"}'::jsonb, 'Contact for current fee & batch structure (NPR)', ARRAY['Python', 'NumPy & Vectorized Computing', 'Pandas DataFrames', 'Matplotlib & Seaborn', 'SQL & Relational Databases', 'Exploratory Data Analysis (EDA)', 'Scikit-Learn', 'Supervised & Unsupervised ML', 'Feature Engineering & Scaling', 'JupyterLab & Google Colab', 'Model Evaluation & Metrics'], ARRAY['Students and graduates in Computer Science, Statistics, Mathematics, Economics, or Business disciplines.', 'Programmers wanting to transition into high-growth Data Science, Business Intelligence, or AI careers.', 'Business analysts seeking to replace manual spreadsheet workflows with automated Python data pipelines.', 'Working professionals aiming to build machine learning models to solve real organizational challenges.'], ARRAY['Basic familiarity with computer usage and high-school mathematics (basic algebra and statistics).', 'Prior exposure to programming logic or completion of Python Beginner is helpful but not strictly required.', 'A laptop with at least 8GB RAM for running data processing notebooks.'], ARRAY['Clean, reshape, and impute missing data from messy real-world datasets using Pandas and NumPy.', 'Conduct comprehensive Exploratory Data Analysis (EDA) and synthesize compelling visual stories with Seaborn.', 'Write complex SQL queries for data aggregation, filtering, joining, and cohort analysis.', 'Train, tune, and evaluate machine learning models (Regression, Classification, Clustering) with Scikit-Learn.', 'Build end-to-end reproducible data science notebooks and deliver actionable business presentations.'], '[{"title":"Exploratory Customer Churn Analysis & Retention Strategy","technologies":["Python","Pandas","Seaborn","Scikit-Learn"],"description":"Comprehensive analysis of telecommunication customer behavior, identifying churn drivers, correlation heatmaps, and building a logistic classification model to predict at-risk users.","type":"Analytics & Predictive Model"},{"title":"Real Estate & Housing Valuation Regression Pipeline","technologies":["Python","Pandas","Scikit-Learn","Feature Engineering"],"description":"Multi-variable regression model predicting property market valuations, featuring automated outlier removal, categorical one-hot encoding, and hyperparameter tuning.","type":"Machine Learning Pipeline"},{"title":"Retail Market Basket Analysis & Product Recommendation Engine","technologies":["Python","Pandas","Association Rules","Matplotlib"],"description":"Unsupervised learning system analyzing thousands of shopping transaction baskets to discover frequent item pairings and generate automated cross-sell recommendations.","type":"Unsupervised Learning"}]'::jsonb, '[]'::jsonb, ARRAY['Data Scientist', 'Data Analyst', 'Business Intelligence (BI) Analyst', 'Machine Learning Associate', 'Quantitative Analytics Specialist'], '{"name":"Lead Data Scientist & ML Researcher","role":"Data Science Faculty Lead","experience":"7+ years in enterprise predictive modeling, big data pipelines, and analytics","specialization":"Pandas, Scikit-Learn, Feature Engineering, Machine Learning, Statistical Inference","isPlaceholder":true}'::jsonb, '[{"question":"Do I need an advanced math or statistics degree for this course?","answer":"No. We teach all necessary statistical concepts—standard deviation, distributions, correlation, p-values, and loss functions—intuitively with visual representations and code."},{"question":"What is the format and duration for 50 days?","answer":"The course runs for 50 intensive instructional days (approx. 8 weeks), with daily live lectures, coding labs in JupyterLab, and weekend project sprints."},{"question":"Will I learn Machine Learning algorithms in this course?","answer":"Yes! You will implement linear and logistic regression, decision trees, random forests, k-means clustering, and model evaluation metrics using Scikit-Learn."}]'::jsonb, 'Data Science Course in Nepal (50 Days) | Python & ML Training Kathmandu', 'Master Data Science in Kathmandu with Navya Ed Tech. Learn Python, Pandas, SQL, and Machine Learning with real-world datasets in our 50-day intensive course.') ON CONFLICT (slug) DO NOTHING;
INSERT INTO programs (slug, title, category, tagline, description, duration, format, eligibility, "whoItsFor", "whatItIncludes", "expectedOutcome", "coursesIncluded") VALUES ('web-development-career-track', 'Modern Web Development Career Track', 'Career Programs', 'Practical, project-based web development from UI foundations to interactive React single-page applications.', 'Our premier frontend and web engineering track designed to bridge the gap between academic theory and commercial web craftsmanship. Spanning semantic HTML5, modern Tailwind CSS styling, JavaScript ES6+ application logic, component-driven React 18+, REST API integration, and cloud deployment on Vercel.', '45 Days (7.5 Weeks)', 'In-Person Computer Lab & Mentored Sprints', 'Open to beginners and students passionate about building modern web software. Personal laptop required.', ARRAY['Students and fresh graduates aspiring to become frontend and web engineers.', 'Career switchers looking to build commercial, production-ready web applications.', 'Designers and tech enthusiasts who want to bring digital interfaces to life with clean code.'], ARRAY['Semantic HTML5, CSS3 Flexbox & Grid, and Tailwind CSS design systems', 'Modern JavaScript ES6+ application logic, array methods, and async/await', 'React 18+ component architecture, hooks, and dynamic state management', 'REST API consumption, third-party data fetching, and single-page application routing', 'Cloud deployment to Vercel with Git branching and GitHub version control', '3 major production capstones: E-Commerce Storefront, Real-Time Kanban Board, and Live API Portal'], ARRAY['Ability to build responsive, accessible web applications independently.', 'Live deployed portfolio containing 3 interactive React applications on Vercel.', 'Fluency in Git branching, pull requests, and modern frontend tooling.'], ARRAY['Web Development']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO programs (slug, title, category, tagline, description, duration, format, eligibility, "whoItsFor", "whatItIncludes", "expectedOutcome", "coursesIncluded") VALUES ('python-data-science-program', 'Python & Applied Data Science Program', 'Career Programs', 'Comprehensive data engineering, statistical modeling, and machine learning for modern analytical roles.', 'An intensive, multi-tier data intelligence pathway taking you from core Python programming and asynchronous FastAPI microservices to high-impact exploratory data analysis, Pandas data wrangling, SQL querying, and predictive machine learning models with Scikit-Learn.', '90 Days (~3 Months)', 'Classroom Immersion / Intensive Laboratory', 'Basic mathematical aptitude (algebra/statistics) and strong motivation for analytical problem solving.', ARRAY['Graduates in CS, IT, BCA, statistics, mathematics, economics, or engineering.', 'Business analysts looking to transition to data science and ML engineering.', 'Software developers wanting to add predictive machine learning capabilities.'], ARRAY['Foundational and advanced object-oriented Python 3 programming', 'High-performance data analysis with NumPy, Pandas & SQL Data Warehousing', 'Exploratory data visualization and statistical trend modeling', 'Scikit-Learn machine learning pipelines and predictive model evaluation', 'FastAPI microservices for serving live machine learning predictions', 'Domain capstones using real Nepali economic, agriculture, and market datasets'], ARRAY['Ability to clean, transform, analyze, and extract business insights from complex datasets.', 'Deployment of machine learning APIs capable of serving live predictions.', 'Statistical reporting and data visualization fluency showcased in a public portfolio.'], ARRAY['Python Beginner', 'Python Advance', 'Data Science']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO programs (slug, title, category, tagline, description, duration, format, eligibility, "whoItsFor", "whatItIncludes", "expectedOutcome", "coursesIncluded") VALUES ('python-software-engineering', 'Python Software Engineering Track', 'Specialized Tracks', 'Master clean object-oriented Python, asynchronous concurrency, and scalable API backend systems.', 'A structured software engineering pathway combining fundamental logic with production-grade backend engineering. Cover internal Python object models, dunder protocols, asynchronous I/O with AsyncIO, concurrency with multiprocessing, decorators, FastAPI microservices, and database ORMs with SQLAlchemy.', '80 Days (~3 Months)', 'Classroom & Hands-On Coding Lab', 'Candidates wanting rigorous programming foundations and production software craftsmanship.', ARRAY['Complete beginners wanting an end-to-end pathway to professional Python programming.', 'College students in BCA, BSc.CSIT, or Engineering seeking strong backend skills.', 'Developers wanting to master asynchronous concurrency and microservice architecture.'], ARRAY['PEP 8 idiomatic Python syntax, data structures, and OOP design patterns', 'File handling, JSON/CSV parsing, and automation scripting', 'Asynchronous I/O with AsyncIO and multiprocessing concurrency', 'FastAPI REST microservice creation, Pydantic validation & SQLAlchemy ORM', 'Unit testing with pytest, Git version control, and GitHub workflows', '3 major projects: Personal Finance Tracker CLI, Async Scraper, and Auth Microservice'], ARRAY['Mastery of professional Python programming from CLI utilities to backend microservices.', 'Ability to architect resilient asynchronous web services with database persistence.', 'A verifiable GitHub portfolio with production code reviewed by senior engineers.'], ARRAY['Python Beginner', 'Python Advance']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO programs (slug, title, category, tagline, description, duration, format, eligibility, "whoItsFor", "whatItIncludes", "expectedOutcome", "coursesIncluded") VALUES ('young-coders-stem-track', 'Young Coders & STEM Foundation Pathway', 'Kids & School Programs', 'Inspiring the next generation of engineers through creative game design and interactive computational logic.', 'A two-stage progressive coding curriculum designed specifically for young learners and school students. Starts with visual block-based storytelling and algorithmic sequencing in Scratch Beginner, and advances into 2D arcade physics, velocity math, collision detection, and multi-level game architecture in Scratch Advanced.', '60 Days (2 Months)', 'Interactive Laboratory & Creative Sprints', 'School students (Grade 4–12) with enthusiasm for creativity, games, and technology. No prior coding required.', ARRAY['School students (+2 and below) taking their first steps in computer science.', 'Young learners interested in creating video games, animations, and interactive stories.', 'Parents seeking structured, creative screen time and computational thinking for kids.'], ARRAY['Visual block-based logic, motion math, and coordinate geometry', 'Event broadcasting, condition trees, loops, and variable state management', 'Custom functions (My Blocks), collision detection, and clone management', '2D arcade platformer game physics, jump mechanics, and enemy waves', 'Interactive capstone game showcase and certificate of achievement'], ARRAY['Strong grasp of foundational computational thinking and algorithmic sequencing.', 'Creation of 6+ published interactive games, animations, and quizzes.', 'Confidence and readiness for transition into text-based coding languages like Python.'], ARRAY['Scratch Beginner', 'Scratch Advanced']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('HimalStore: Modern E-Commerce Storefront & Cart', 'Web Development', ARRAY['React', 'Tailwind CSS', 'JavaScript ES6+', 'REST APIs', 'Vercel'], 'A responsive e-commerce web application engineered during the Web Development course. Features dynamic product filtering, price sorting, interactive shopping cart with local state synchronization, and mock checkout flow.', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=800&q=80', 'Web Development Capstone Project', ARRAY['Component-driven architecture in React 18+ with custom state hooks', 'Responsive mobile-first layout with modern Tailwind CSS utilities', 'Deployed to production on Vercel with automated GitHub sync'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('TaskFlow: Interactive Real-Time Kanban Board', 'Web Development', ARRAY['React', 'JavaScript ES6+', 'CSS Grid', 'REST APIs', 'Vercel'], 'A project management dashboard designed to streamline agile team workflows. Users can create, edit, tag, and re-order tasks across custom sprint stages with persistent local storage and dynamic theme controls.', 'https://images.unsplash.com/photo-1507238691740-187a5b1d37b8?auto=format&fit=crop&w=800&q=80', 'Web Development Intermediate Project', ARRAY['Drag-and-drop state handling and optimistic UI updates', 'Accessible keyboard navigation and dark/light color palette', 'Connected to live mock REST API endpoints for seamless data flow'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('KrishiForecast: Vegetable Price Trend Predictor (Kalimati Market)', 'Data Science', ARRAY['Python', 'Pandas', 'NumPy', 'Scikit-Learn', 'Matplotlib'], 'A data science system trained on historical daily price datasets from the Kalimati vegetable market. Cleans time-series data, analyzes seasonal volatility indices, and builds regression models to forecast agricultural staple prices.', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=800&q=80', 'Data Science Capstone Project', ARRAY['Rigorous time-series data cleaning and outlier imputation in Pandas', 'Random Forest regression model with 88% directional accuracy', 'Interactive statistical charts and price trend distribution plots'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('NepalGhar: Housing Valuation & Real Estate Analytics', 'Data Science', ARRAY['Python', 'Pandas', 'Scikit-Learn', 'Seaborn', 'SQL'], 'A predictive real estate analytics pipeline analyzing Kathmandu housing metrics (square footage, road access, location zones). Implements feature scaling, multi-variable linear regression, and model evaluation metrics.', 'https://images.unsplash.com/photo-1557404763-69708cd8b9ce?auto=format&fit=crop&w=800&q=80', 'Data Science Machine Learning Project', ARRAY['Comprehensive correlation matrix and feature importance ranking', 'K-Fold cross-validation and RMSE error metric scoring', 'Structured data pipeline from raw CSV ingestion to prediction report'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('FinTrack: Automated Personal Expense & Analytics CLI', 'Python Engineering', ARRAY['Python 3.12', 'OOP', 'JSON / CSV', 'CLI', 'Git'], 'A modular command-line application designed in Python Beginner. Parses multi-month expense records, performs categorical breakdown, calculates monthly savings rates, and exports formatted financial audit summaries.', 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?auto=format&fit=crop&w=800&q=80', 'Python Beginner Capstone Project', ARRAY['Object-oriented architecture with clean, reusable domain models', 'Robust error handling for corrupt file records and malformed JSON', 'CLI interface with interactive terminal prompt workflows'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('FastScrape: Asynchronous Ingestion & Microservice Engine', 'Python Engineering', ARRAY['Python', 'FastAPI', 'AsyncIO', 'SQLAlchemy', 'Pydantic'], 'Built during Python Advance to demonstrate high-throughput concurrency. Uses AsyncIO and AIOHTTP to scrape, validate, and persist tech listings into a relational database exposed via authenticated REST endpoints.', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=800&q=80', 'Python Advance Engineering Project', ARRAY['Non-blocking asynchronous I/O ingestion engine handling 100+ concurrent requests', 'Pydantic schema validation and automatic OpenAPI documentation', 'SQLAlchemy ORM models with connection pooling and query optimization'], FALSE);
INSERT INTO student_projects (title, category, technologies, description, image, "completionContext", highlights, "isPlaceholder") VALUES ('Space Defenders: Multi-Level 2D Arcade Physics Platformer', 'Kids Coding', ARRAY['Scratch 3.0', 'Velocity Physics', 'Sprite Clones', 'Collision Math'], 'An arcade platformer game created in Scratch Advanced by young coders. Features jumping gravity physics, multi-wave enemy clone spawning, projectile collisions, dynamic score counters, and progressive boss battles.', 'https://images.unsplash.com/photo-1450133064473-71024230f91b?auto=format&fit=crop&w=800&q=80', 'Scratch Advanced Capstone Project', ARRAY['Custom velocity physics blocks simulating realistic jump gravity', 'Algorithmic enemy spawn waves using sprite cloning', 'Interactive sound effects, boss battle phases, and high-score saves'], FALSE);
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('navigating-modern-software-engineering-careers-in-nepal', 'Navigating Modern Software Engineering Careers in Nepal: Skills, Portfolios & Industry Demands', 'An objective analysis of how the IT hiring landscape in Kathmandu and remote tech companies has shifted from memorizing syntax to evaluating architecture, Git hygiene, and end-to-end project execution.', 'Nepal IT Industry', 'August 2026', '6 min read', '{"name":"Engineering Advisory Guild","role":"Senior Software Practitioners & Educators","avatarUrl":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80","bio":"The Engineering Advisory Guild at Navya Ed Tech brings together veteran engineers from product studios and offshore development centers across Nepal."}'::jsonb, 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1200&q=80', ARRAY['The technology employment landscape in Nepal is undergoing a profound evolution. While early industry roles prioritized basic scripting or static website templating, modern product studios and offshore development centers look for candidates who can think in systems, collaborate using Git, and understand deployment mechanics.', '## The Shift from Syntax to Systems Architecture', 'One of the most frequent gaps our engineering leads observe in fresh university graduates (BSc.CSIT, BCA, BIT, and BE) is the separation between theoretical syllabus concepts and practical product engineering. Knowing what an array is or memorizing textbook definitions does not automatically translate into understanding how to handle asynchronous data fetching, prevent SQL injection, or design responsive UI components that do not re-render unnecessarily.', 'Today, engineering recruiters in Nepal evaluate candidates along four concrete dimensions: architectural discipline, database fluency, error handling & edge cases, and verifiable deployment pipelines. An applicant who can clearly explain why they chose PostgreSQL over MongoDB for a specific data model instantly stands out in an interview.', '## What Makes a Verifiable Portfolio Stand Out', 'Generic clones of Netflix, Spotify, or To-Do apps rarely impress senior hiring panels because hiring managers recognize boilerplate tutorial code immediately. Instead, employers look for applications that solve localized or domain-specific challenges with production considerations:', '• Multi-role authentication with protected routes and JWT refresh token rotation.
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('why-project-based-learning-outperforms-passive-tutorials', 'The "Tutorial Trap" in Programming: Why Building Under Constraint Drives Real Competency', 'Why watching hours of coding tutorials rarely produces job-ready developers, and how deliberate practice with code reviews builds true problem-solving resilience.', 'Programming', 'July 2026', '5 min read', '{"name":"Technical Education Team","role":"Curriculum & Pedagogy Specialists","avatarUrl":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","bio":"Leading curriculum design and project evaluation standards at Navya Ed Tech."}'::jsonb, 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?auto=format&fit=crop&w=1200&q=80', ARRAY['Passive video consumption creates a deceptive illusion of competence. When following a tutorial video step-by-step, the instructor has already solved the architectural dilemmas, handled the edge cases, and cleaned up the bugs off-camera. You feel like you are learning rapidly because code appears on your screen and runs smoothly.', 'Yet the moment aspiring engineers close the tutorial and open an empty editor to build a project from scratch, they frequently experience a paralyzing mental block. This phenomenon is widely known as the "Tutorial Trap".', '## The Science of Deliberate Practice & Debugging', 'Real engineering competence begins the moment your build fails and you must inspect stack traces, consult official documentation, and formulate hypotheses to resolve the bug. The struggle of resolving an `UnhandledPromiseRejection` or diagnosing why a React component is triggering an infinite re-render loop is precisely where synaptic connections and engineering intuition are formed.', 'When students are forced to translate a product specification into database schemas and API endpoints without step-by-step hand-holding, they develop problem-solving resilience that cannot be acquired through video consumption alone.', '## How Navya Ed Tech Structures Project-Driven Sprints', 'At Navya Ed Tech, we structure all coursework around guided project sprints with mandatory code critiques. When students learn to defend their schema choices and refactor their own code following feedback from senior mentors, their retention and debugging speed increase drastically.', 'Every student is evaluated on code readability, test coverage, and documentation clarity—ensuring they enter the software industry as disciplined, autonomous contributors.'], ARRAY['Learning Methodology', 'Code Reviews', 'Productivity', 'Engineering Habits']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('why-typescript-is-essential-for-modern-web-development', 'Why TypeScript Has Become Non-Negotiable in Production Web Teams', 'Exploring how static typing prevents entire classes of runtime defects, improves IDE developer experience, and enables fearless refactoring in growing codebases.', 'Web Development', 'June 2026', '7 min read', '{"name":"Frontend Engineering Guild","role":"Navya EdTech Practitioners","avatarUrl":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80","bio":"Practitioners specializing in React, Next.js, and large-scale TypeScript architecture."}'::jsonb, 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=1200&q=80', ARRAY['As web applications grow in complexity, dynamic typing in pure JavaScript often leads to silent runtime errors, difficult refactorings, and undocumented API contracts between teams. In a commercial environment where multiple engineers collaborate on the same repository, a single typo in a property name can cause critical user-facing crashes.', 'TypeScript has evolved from an optional luxury to an industry standard. Today, virtually all modern React, Next.js, and Node.js teams in top software studios mandate TypeScript for production repositories.', '## Preventing Runtime Failures Before Code Reaches Staging', 'The classic `TypeError: Cannot read properties of undefined (reading ''map'')` is one of the most common exceptions in JavaScript. With TypeScript, such errors are caught in your code editor before you even save the file. By enforcing strict null checks and defining explicit data contracts, your tools tell you exactly when a property might be optional or null.', 'Furthermore, TypeScript turns your codebase into self-documenting software. When a new engineer joins a project, they do not need to decipher undocumented JSON objects or guess what fields an API endpoint returns; the interfaces and types provide an instant blueprint.', '## Fearless Refactoring in Scale Codebases', 'Consider renaming a core data model attribute across a 50,000-line application. In JavaScript, this requires global search-and-replace and crossing your fingers during QA testing. In TypeScript, renaming a symbol updates every single reference across the workspace, and the compiler instantly flags any overlooked discrepancies.', 'In our Web Development courses, modern JavaScript and React are taught alongside component contracts so students build muscle memory with clean architecture, strict linting, and predictable data flow from day one.'], ARRAY['TypeScript', 'React', 'Frontend', 'Best Practices', 'Code Quality']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('demystifying-ai-and-python-in-modern-engineering', 'Demystifying AI & Python in 2026: From Scripting Basics to Production LLM & ML Pipelines', 'A pragmatic guide to navigating Python programming, data analytics, machine learning foundations, and modern generative AI application development without getting lost in hype.', 'AI', 'May 2026', '8 min read', '{"name":"Data & AI Research Group","role":"Machine Learning Engineers","avatarUrl":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=200&q=80","bio":"Focusing on practical applied AI, vector embeddings, predictive analytics, and Python engineering."}'::jsonb, 'https://images.unsplash.com/photo-1555949963-ff9fe0c870eb?auto=format&fit=crop&w=1200&q=80', ARRAY['Artificial Intelligence has transformed from an academic research domain into an essential toolkit for modern software developers. However, the overwhelming flood of new models, frameworks, and buzzwords often leaves students confused about where to start and what skills actually matter.', 'To build a genuine career in AI and data engineering, you must cut through the hype and master the foundational layers that underpin every intelligent system.', '## The Python Bedrock: Clean Syntax and Data Manipulation', 'Python remains the undisputed lingua franca of data science and artificial intelligence. Its expansive ecosystem—powered by NumPy, Pandas, Matplotlib, and Scikit-Learn—allows developers to inspect, clean, and model complex datasets with remarkable efficiency.', 'Before jumping into deep neural networks or generative AI, an engineer must understand vectorized array operations, data normalization, outlier detection, and statistical validation. Without high-quality data, even the most sophisticated neural architectures produce unreliable predictions.', '## Applied AI in 2026: RAG, Embeddings & Vector Search', 'The modern software engineer is rarely required to train an LLM from scratch. Instead, industry demand centers on building intelligent applications that integrate domain data with foundational models using Retrieval-Augmented Generation (RAG).', 'By chunking organizational documents, computing dense vector embeddings, and querying vector databases, developers create accurate, hallucination-resistant knowledge assistants.', 'In our Python, Data Science & AI curriculum, students build both traditional predictive models (regression, classification, clustering) and cutting-edge generative AI applications connected to real SQL and vector datastores.'], ARRAY['Python', 'Machine Learning', 'Artificial Intelligence', 'Data Science', 'LLMs']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('full-stack-system-architecture-guide-for-scalable-apps', 'Full-Stack System Architecture: Database Optimization, Caching & Cloud Deployments', 'An engineering overview of building resilient full-stack systems: handling database connection pools, configuring Redis caches, and deploying with Docker and CI/CD.', 'Technology', 'April 2026', '7 min read', '{"name":"Cloud & Systems Guild","role":"DevOps & Backend Engineers","avatarUrl":"https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=200&q=80","bio":"Specialists in container orchestration, cloud infrastructure, and backend scalability."}'::jsonb, 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=1200&q=80', ARRAY['Building an application that works on `localhost:3000` with one user is relatively straightforward. Building a system that remains fast, secure, and available when hundreds of simultaneous users interact with it is the true test of software engineering.', 'Understanding system architecture is what transforms a code writer into a comprehensive software engineer capable of leading high-impact initiatives.', '## Database Performance: Indexes and Connection Pooling', 'The database is almost always the first bottleneck in a scaling web application. Frequent full-table scans cause query times to degrade from milliseconds to seconds as tables grow. By establishing proper composite indexes and analyzing query execution plans with `EXPLAIN ANALYZE`, developers can dramatically boost throughput.', 'Equally important is connection pooling. Opening and closing database connections on every HTTP request consumes significant CPU overhead. Implementing connection pool managers allows backend servers to reuse connections efficiently under heavy load.', '## Containerization and Reproducible Deployments', 'The notorious excuse "it worked on my machine" is unacceptable in professional software organizations. Docker containerization packages application source code, runtime dependencies, and configuration files into lightweight, immutable images.', 'Combined with automated GitHub Actions workflows, developers can run automated test suites on every pull request and deploy zero-downtime updates to cloud environments with total confidence.'], ARRAY['Architecture', 'Cloud', 'PostgreSQL', 'Docker', 'DevOps']) ON CONFLICT (slug) DO NOTHING;
INSERT INTO insights (slug, title, excerpt, category, date, "readTime", author, "coverImage", content, tags) VALUES ('ui-ux-design-systems-how-product-studios-hire', 'UI/UX Design Systems vs Graphic Design: How Modern Product Studios Evaluate Designers', 'An insider look at how technology companies assess UI/UX designers: moving beyond visual aesthetics to design systems, accessibility, and user flows.', 'Digital Skills', 'March 2026', '6 min read', '{"name":"Product Design Practice","role":"UI/UX Designers & UX Researchers","avatarUrl":"https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?auto=format&fit=crop&w=200&q=80","bio":"Focusing on frontend user experience, accessibility, and modern design system implementations at Navya Ed Tech."}'::jsonb, 'https://images.unsplash.com/photo-1581291518633-83b4ebd1d83e?auto=format&fit=crop&w=1200&q=80', ARRAY['There is a common misconception among beginners that UI/UX design is synonymous with graphic design or digital illustration. While graphic design focuses on visual expression, branding, and aesthetics, product design is fundamentally concerned with user behavior, information architecture, and system usability.', 'When software studios hire UI/UX designers, they look beyond polished Dribbble mockups to evaluate how deeply a designer understands the user journey and technical constraints.', '## Design Systems and Component Scalability in Figma', 'In modern software teams, designers do not create isolated one-off screens. Instead, they architect comprehensive design systems composed of standardized color tokens, typographic hierarchies, spacing systems, and atomic components (buttons, input fields, modals, and navigation bars).', 'By utilizing Figma features like Auto Layout, Component Properties, and Variable Modes (such as Light and Dark mode tokens), designers produce assets that directly translate into reusable React or Tailwind CSS components for the engineering team.', '## Usability Testing and Evidence-Based Decisions', 'A defensible design decision is backed by user research and usability testing, not personal aesthetic preferences. Knowing how to conduct user interviews, map out friction points in an onboarding flow, and interpret analytical metrics is what distinguishes senior product designers.', 'In our Web Development and frontend coursework, students learn the fundamentals of clean UI layouts, accessible component hierarchies, and translating design tokens directly into responsive React interfaces.'], ARRAY['UI/UX Design', 'Design Systems', 'Figma', 'Accessibility', 'Product Strategy']) ON CONFLICT (slug) DO NOTHING;
